// A print with a wide white border: the scene is the photo, and its name is
// written along the bottom edge.
const on = (value) => value === true || value === 'true'
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']

export function get(app) {
  const { caption, paperColor, inkColor, showDate } = app.state
  const now = new Date()
  return (
    <div className={`flex flex-col w-full h-full p-[4vh] bg-[${paperColor}] text-[${inkColor}]`}>
      <div className="flex flex-col flex-1 min-h-0">
        <yield />
      </div>
      <div className="flex items-center h-[12vh] pt-[2vh] gap-[3vw]">
        <span className="flex-1 text-[5.5vh] font-semibold truncate">{caption || app.frame.sceneName || ''}</span>
        {on(showDate) ? (
          <span className="text-[3.4vh] whitespace-nowrap">{`${now.getDate()} ${MONTHS[now.getMonth()]}`}</span>
        ) : null}
      </div>
    </div>
  )
}
